import json, os, csv, io
m=json.load(open('inputs/manifest.json'))
print('manifest_keys', list(m.keys()))
print(json.dumps(m, ensure_ascii=False)[:1200])

paths=[]
def walk(o):
    if isinstance(o,dict):
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
    elif isinstance(o,str):
        if o.lower().endswith('.csv') or 'inventory' in o.lower(): paths.append(o)
walk(m)
print('paths', sorted(set(paths))[:20])

cands=[p for p in sorted(set(paths)) if p.lower().endswith('.csv')]
for p in cands[:3]:
    if not os.path.exists(p):
        print('missing', p); continue
    raw=open(p,'rb').read()
    print('file', p, 'bytes', len(raw), 'head_bytes', raw[:60])
    try:
        txt=raw.decode('utf-8-sig')
        enc='utf-8-sig'
    except Exception as e:
        txt=raw.decode('cp874'); enc='cp874'
    print('enc', enc)
    lines=txt.splitlines()
    print('n_lines', len(lines))
    for i,l in enumerate(lines[:4]):
        print(i, repr(l))
    print('last', repr(lines[-1]))
    rows=list(csv.reader(io.StringIO(txt)))
    print('header', rows[0])
    print('row1', rows[1])
    skus=[r[0] for r in rows[1:] if r]
    print('sku sample repr', [repr(s) for s in skus[:4]], 'len_uniq', sorted(set(len(s) for s in skus)))
    import collections
    print('loc_counts', collections.Counter(r[8] for r in rows[1:] if len(r)>8))

